"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  DEPARTMENT_ALL,
  DEPARTMENT_OPTIONS,
  PRODUCT_ALL,
  PRODUCT_OPTIONS,
  REGION_OPTIONS,
  useDashboardFilters,
} from "@/components/dashboard/DashboardFilters";
import { FilterDatePicker } from "@/components/dashboard/FilterDatePicker";
import {
  IconChevronDown,
  IconGlobe,
  IconInfo,
  IconRefresh,
} from "@/components/icons";
import { cn } from "@/lib/utils";

const periods = ["Week", "Month", "Quarter", "Year", "Custom"] as const;

const chipClass =
  "inline-flex h-10 items-center gap-2 rounded-lg border border-icr-border bg-icr-surface px-3 text-sm text-icr-navy";

export function PageHeader() {
  return (
    <div className="flex items-start justify-between gap-4">
      <div>
        <h1 className="m-0 text-[28px] font-bold leading-9 tracking-[-0.02em] text-icr-navy">
          Welcome back, Olivia
        </h1>
        <p className="mt-1 mb-0 text-sm text-icr-muted">
          Summary from Last activity 30 days
        </p>
      </div>
      <div className="inline-flex h-10 items-center gap-3 rounded-lg border border-icr-border bg-icr-surface px-3 text-[13px] text-icr-muted">
        <button
          type="button"
          className="inline-flex items-center gap-1.5 font-medium text-icr-navy"
        >
          <IconRefresh />
          Refresh
        </button>
        <span className="h-4 w-px bg-icr-border" aria-hidden />
        <span>Updated 11:38 PM</span>
      </div>
    </div>
  );
}

function FilterDropdown({
  label,
  open,
  onToggle,
  children,
  active,
  leading,
}: {
  label: ReactNode;
  open: boolean;
  onToggle: () => void;
  children: ReactNode;
  active?: boolean;
  leading?: ReactNode;
}) {
  return (
    <div className="relative">
      <button
        type="button"
        aria-expanded={open}
        onClick={onToggle}
        className={cn(
          chipClass,
          active && "border-icr-orange bg-icr-orange-soft",
        )}
      >
        {leading}
        {label}
        <span
          className={cn(
            "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
            open && "rotate-180",
          )}
        >
          <IconChevronDown />
        </span>
      </button>
      <div
        className={cn(
          "absolute top-[calc(100%+8px)] left-0 z-30 min-w-full origin-top transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
          open
            ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
            : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
        )}
      >
        <div className="overflow-hidden rounded-lg border border-icr-border bg-white py-1 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
          {children}
        </div>
      </div>
    </div>
  );
}

export function FilterBar() {
  const {
    region,
    department,
    product,
    setRegion,
    setDepartment,
    setProduct,
    clearFilters,
    activeCount,
    regionActive,
    departmentActive,
    productActive,
  } = useDashboardFilters();

  const [period, setPeriod] = useState<(typeof periods)[number]>("Month");
  const [regionOpen, setRegionOpen] = useState(false);
  const [deptOpen, setDeptOpen] = useState(false);
  const [productOpen, setProductOpen] = useState(false);
  const [baselineOpen, setBaselineOpen] = useState(false);
  const [baseline, setBaseline] = useState("Previous 6 months");
  const [fromDate, setFromDate] = useState("09-10-2025");
  const [toDate, setToDate] = useState("09-10-2025");
  const customOpen = period === "Custom";
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDoc(e: MouseEvent) {
      if (!rootRef.current?.contains(e.target as Node)) {
        setRegionOpen(false);
        setDeptOpen(false);
        setProductOpen(false);
        setBaselineOpen(false);
      }
    }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  function closeMenus() {
    setRegionOpen(false);
    setDeptOpen(false);
    setProductOpen(false);
    setBaselineOpen(false);
  }

  return (
    <div
      ref={rootRef}
      className="relative flex flex-wrap items-start justify-between gap-4"
    >
      <div className="flex flex-wrap items-center gap-2.5">
        <FilterDropdown
          active={regionActive}
          open={regionOpen}
          onToggle={() => {
            setDeptOpen(false);
            setProductOpen(false);
            setBaselineOpen(false);
            setRegionOpen((v) => !v);
          }}
          leading={
            <IconGlobe
              size={14}
              className={regionActive ? "text-icr-orange" : "text-icr-muted"}
            />
          }
          label={
            <>
              <span className="text-[13px] text-icr-muted">Region:</span>
              {regionActive ? region : "All"}
            </>
          }
        >
          {REGION_OPTIONS.map((item) => (
            <button
              key={item}
              type="button"
              className={cn(
                "flex w-full px-3 py-2 text-left text-sm hover:bg-[#F8F9FA]",
                item === region
                  ? "bg-icr-orange-soft font-medium text-icr-orange"
                  : "text-icr-navy",
              )}
              onClick={() => {
                setRegion(item);
                setRegionOpen(false);
              }}
            >
              {item}
            </button>
          ))}
        </FilterDropdown>

        <FilterDropdown
          active={departmentActive}
          open={deptOpen}
          onToggle={() => {
            setRegionOpen(false);
            setProductOpen(false);
            setBaselineOpen(false);
            setDeptOpen((v) => !v);
          }}
          label={departmentActive ? department : DEPARTMENT_ALL}
        >
          {DEPARTMENT_OPTIONS.map((item) => (
            <button
              key={item}
              type="button"
              className={cn(
                "flex w-full px-3 py-2 text-left text-sm hover:bg-[#F8F9FA]",
                item === department
                  ? "bg-icr-orange-soft font-medium text-icr-orange"
                  : "text-icr-navy",
              )}
              onClick={() => {
                setDepartment(item);
                setDeptOpen(false);
              }}
            >
              {item}
            </button>
          ))}
        </FilterDropdown>

        <FilterDropdown
          active={productActive}
          open={productOpen}
          onToggle={() => {
            setRegionOpen(false);
            setDeptOpen(false);
            setBaselineOpen(false);
            setProductOpen((v) => !v);
          }}
          label={productActive ? product : PRODUCT_ALL}
        >
          {PRODUCT_OPTIONS.map((item) => (
            <button
              key={item}
              type="button"
              className={cn(
                "flex w-full px-3 py-2 text-left text-sm hover:bg-[#F8F9FA]",
                item === product
                  ? "bg-icr-orange-soft font-medium text-icr-orange"
                  : "text-icr-navy",
              )}
              onClick={() => {
                setProduct(item);
                setProductOpen(false);
              }}
            >
              {item}
            </button>
          ))}
        </FilterDropdown>

        {activeCount > 0 ? (
          <button
            type="button"
            onClick={() => {
              clearFilters();
              closeMenus();
            }}
            className="text-[13px] font-medium text-icr-orange"
          >
            {activeCount === 1
              ? "Clear filters"
              : `Clear ${activeCount} filters`}
          </button>
        ) : null}
      </div>

      <div className="relative flex flex-wrap items-center gap-2">
        <div className="relative">
          <div
            className="inline-flex items-start rounded-[10px] bg-white p-1"
            style={{
              outline: "1px solid rgba(13, 24, 61, 0.15)",
              outlineOffset: "-1px",
            }}
          >
            {periods.map((p) => {
              const active = period === p;
              return (
                <button
                  key={p}
                  type="button"
                  className={cn(
                    "flex items-start gap-1 text-[12px] font-medium leading-[15.6px] transition-colors duration-200",
                    active
                      ? "rounded-lg px-2.5 py-[9px] text-[#F6861F]"
                      : "rounded-[7px] px-2 py-[9px] text-[#617385]",
                  )}
                  style={
                    active
                      ? {
                          background:
                            "linear-gradient(0deg, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.95)), #F6861F",
                          outline: "1px solid rgba(246, 134, 31, 0.55)",
                          outlineOffset: "-1px",
                        }
                      : undefined
                  }
                  onClick={() => {
                    setPeriod(p);
                    closeMenus();
                  }}
                >
                  {p}
                </button>
              );
            })}
          </div>

          <div
            className={cn(
              "absolute top-[calc(100%+8px)] right-0 z-30 origin-top-right transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
              customOpen
                ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
                : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
            )}
          >
            <div className="inline-flex items-center gap-3 whitespace-nowrap rounded-xl border border-[#DBDDE2] bg-white px-3 py-2.5 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
              <FilterDatePicker
                label="From"
                value={fromDate}
                onChange={setFromDate}
              />
              <FilterDatePicker
                label="To"
                value={toDate}
                onChange={setToDate}
              />
              <button
                type="button"
                className="h-10 shrink-0 rounded-lg bg-icr-orange px-4 text-sm font-medium text-white"
                onClick={() => setPeriod("Custom")}
              >
                Apply
              </button>
            </div>
          </div>
        </div>

        <div
          className="relative inline-flex items-stretch rounded-[10px] bg-white"
          style={{
            outline: "1px solid rgba(13, 24, 61, 0.15)",
            outlineOffset: "-1px",
          }}
        >
          <span className="group/baseline relative inline-flex items-center gap-1 rounded-l-[10px] bg-[#E8EEF4] px-3 py-[9px] text-[12px] font-medium leading-[15.6px] text-[#617385]">
            Baseline Median
            <span className="relative inline-flex">
              <IconInfo size={12} className="cursor-help" />
              <span className="pointer-events-none invisible absolute bottom-[calc(100%+10px)] left-1/2 z-40 w-[280px] -translate-x-1/2 opacity-0 transition-opacity duration-150 group-hover/baseline:visible group-hover/baseline:opacity-100">
                <span className="relative block rounded-2xl bg-white px-4 py-3 text-left text-[12px] font-normal leading-[18px] text-icr-navy shadow-[0_8px_28px_rgba(16,24,40,0.18)]">
                  Past Average shows the middle value of the period selected for
                  all metrics, not including the current time period. It
                  provides a comparison against today&apos;s number to see if
                  current performance is normal or unusual.
                  <span
                    className="absolute top-full left-1/2 -mt-px -translate-x-1/2 border-x-[7px] border-t-[8px] border-x-transparent border-t-white"
                    aria-hidden
                  />
                </span>
              </span>
            </span>
          </span>
          <button
            type="button"
            aria-expanded={baselineOpen}
            onClick={() => {
              setRegionOpen(false);
              setDeptOpen(false);
              setProductOpen(false);
              setBaselineOpen((v) => !v);
            }}
            className="inline-flex items-center gap-2 rounded-r-[10px] border-l border-[rgba(13,24,61,0.15)] bg-white px-3 py-[9px] text-[12px] font-medium leading-[15.6px] text-[#617385]"
          >
            {baseline}
            <span
              className={cn(
                "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
                baselineOpen && "rotate-180",
              )}
            >
              <IconChevronDown size={12} />
            </span>
          </button>
          <div
            className={cn(
              "absolute top-[calc(100%+8px)] right-0 z-30 min-w-full origin-top transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
              baselineOpen
                ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
                : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
            )}
          >
            <div className="overflow-hidden rounded-lg border border-icr-border bg-white py-1 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
              {[
                "Previous 6 months",
                "Previous 3 months",
                "Previous 12 months",
              ].map((item) => (
                <button
                  key={item}
                  type="button"
                  className={cn(
                    "flex w-full px-3 py-2 text-left text-sm hover:bg-[#F8F9FA]",
                    item === baseline
                      ? "bg-icr-orange-soft font-medium text-icr-orange"
                      : "text-icr-navy",
                  )}
                  onClick={() => {
                    setBaseline(item);
                    setBaselineOpen(false);
                  }}
                >
                  {item}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
