const columns = [
  { key: "lead", label: "Lead", className: "min-w-[200px]" },
  { key: "customer", label: "Customer", className: "min-w-[140px]" },
  { key: "product", label: "Product", className: "min-w-[120px]" },
  { key: "region", label: "Region", className: "min-w-[120px]" },
  { key: "department", label: "Department", className: "min-w-[120px]" },
  { key: "state", label: "State", className: "min-w-[100px] text-center" },
  { key: "age", label: "Age / Cycle", className: "min-w-[100px] text-center" },
  { key: "status", label: "Status", className: "min-w-[120px] text-center" },
  { key: "action", label: "Action", className: "w-[88px] text-center" },
] as const;

function StatusBadge({ status }: { status: LeadDetail["status"] }) {
  if (status === "At Risk") {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-[#FCF3E0] px-[7px] py-0.5 text-[10px] font-medium leading-[15px] text-[#DD9800]">
        <IconWarning size={9} />
        At Risk
      </span>
    );
  }
  if (status === "Breached") {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-[#FCE0E0] px-[7px] py-0.5 text-[10px] font-medium leading-[15px] text-[#EC0004]">
        <IconXCircle size={9} />
        Breached
      </span>
    );
  }
  return (
    <span className="inline-flex items-center rounded-full bg-[#ECF0F5] px-[7px] py-0.5 text-[10px] font-medium leading-[15px] text-[#617385]">
      Within SLA
    </span>
  );
}

function FilterChip({
  label,
  onRemove,
}: {
  label: string;
  onRemove: () => void;
}) {
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-[#FDF1E6] px-2.5 py-1 text-[11px] font-medium text-icr-navy">
      {label}
      <button
        type="button"
        onClick={onRemove}
        aria-label={`Remove ${label}`}
        className="text-[rgba(29,54,80,0.7)]"
      >
        <IconTagX size={10} />
      </button>
    </span>
  );
}

export function LeadRegister() {
  const {
    region,
    department,
    product,
    regionActive,
    departmentActive,
    productActive,
    clearRegion,
    clearDepartment,
    clearProduct,
  } = useDashboardFilters();

  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<LeadDetail | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return leads.filter((lead) => {
      if (regionActive && lead.region !== region) return false;
      if (departmentActive && lead.department !== department) return false;
      if (productActive && lead.product !== product) return false;
      if (!q) return true;
      return (
        lead.id.toLowerCase().includes(q) ||
        lead.customer.toLowerCase().includes(q) ||
        lead.title.toLowerCase().includes(q)
      );
    });
  }, [
    query,
    region,
    department,
    product,
    regionActive,
    departmentActive,
    productActive,
  ]);

  function openLead(lead: LeadDetail) {
    setSelected(lead);
    setDrawerOpen(true);
  }

  function closeDrawer() {
    setDrawerOpen(false);
  }

  return (
    <>
      <section className="flex flex-col gap-6 rounded-[14px] border border-[rgba(13,24,61,0.15)] bg-white py-4">
        <div className="flex items-start gap-2.5 px-4">
          <div className="min-w-0 flex-1">
            <h2 className="m-0 text-base font-medium leading-5 text-icr-navy">
              Lead register
            </h2>
            <p className="m-0 text-xs leading-[16.8px] text-[rgba(29,54,80,0.65)]">
              Full list of leads. Selecting a section above filters this table
              automatically.
            </p>
            {regionActive || departmentActive || productActive ? (
              <div className="mt-2 flex flex-wrap items-center gap-1.5">
                {regionActive ? (
                  <FilterChip
                    label={`Region: ${region}`}
                    onRemove={clearRegion}
                  />
                ) : null}
                {departmentActive ? (
                  <FilterChip
                    label={`Department: ${department}`}
                    onRemove={clearDepartment}
                  />
                ) : null}
                {productActive ? (
                  <FilterChip
                    label={`Product: ${product}`}
                    onRemove={clearProduct}
                  />
                ) : null}
              </div>
            ) : null}
          </div>
          <label className="flex h-9 w-[280px] shrink-0 items-center gap-2 overflow-hidden rounded-lg border border-[#E6EBF1] bg-white px-2.5 font-[family-name:var(--font-geist)] text-xs text-[#6C7C8D]">
            <IconSearch size={14} />
            <input
              type="search"
              placeholder="Search leads or customers…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="w-full border-none bg-transparent text-icr-navy outline-none placeholder:text-[#6C7C8D]"
            />
          </label>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[1100px] border-collapse">
            <thead>
              <tr>
                {columns.map((col) => (
                  <th
                    key={col.key}
                    className={cn(
                      "h-[39px] border-b border-[rgba(13,24,61,0.1)] bg-[#F8F9FA] px-3 py-3 text-left text-[10px] font-medium uppercase leading-[15px] tracking-[0.25px] text-[#617385]",
                      col.className,
                    )}
                  >
                    <span className="inline-flex items-center gap-1">
                      {col.label}
                      {col.key !== "action" ? (
                        <IconSort className="opacity-80" />
                      ) : null}
                    </span>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td
                    colSpan={columns.length}
                    className="px-4 py-10 text-center text-sm text-[#617385]"
                  >
                    No leads match the current filters.
                  </td>
                </tr>
              ) : (
                filtered.map((lead) => (
                  <tr key={lead.id} className="group">
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-4 py-4 align-middle">
                      <div className="flex flex-col">
                        <span className="text-sm font-medium leading-[20.3px] text-icr-navy">
                          {lead.id}
                        </span>
                        <span className="text-xs leading-[16.8px] text-[#9AA1A8]">
                          {lead.title}
                        </span>
                      </div>
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-4 py-4 align-middle text-[10px] font-medium leading-[15px] text-icr-navy">
                      {lead.customer}
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 align-middle text-[10px] font-medium leading-[15px] text-icr-navy">
                      {lead.product}
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 align-middle text-[10px] font-medium leading-[15px] text-icr-navy">
                      {lead.region}
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 align-middle text-[10px] font-medium leading-[15px] text-icr-navy">
                      {lead.department}
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 text-center align-middle">
                      <span className="inline-flex items-center gap-1.5 rounded-full bg-[#E9FDF3] px-[7px] py-0.5 text-[10px] font-medium leading-[15px] text-[#0D9B91]">
                        <span className="size-1.5 rounded-full bg-[#0D9B91]" />
                        Active
                      </span>
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 text-center align-middle text-[10px] font-medium leading-[15px] text-icr-navy">
                      {lead.age}
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-3 py-4 text-center align-middle">
                      <StatusBadge status={lead.status} />
                    </td>
                    <td className="h-[68px] border-b border-[rgba(13,24,61,0.1)] px-4 py-4 text-center align-middle">
                      <button
                        type="button"
                        onClick={() => openLead(lead)}
                        className="inline-flex h-8 w-12 items-center justify-center rounded-xl bg-[#F8F9FA] text-icr-navy transition-colors hover:bg-[#ECF0F5]"
                        aria-label={`Open ${lead.id}`}
                      >
                        <IconChevronRight size={12} />
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        <div className="flex items-center justify-between gap-3 rounded-[20px] bg-white px-3 py-3 pl-4">
          <div className="inline-flex items-center gap-2.5 text-base text-[#434343]">
            Show by:
            <button
              type="button"
              className="inline-flex h-10 w-[122px] items-center justify-between rounded-xl border border-[#E9EBEE] bg-[#F8FAFB] px-3 text-base text-[#7E848A] opacity-75"
            >
              7 items
              <IconChevronDown size={12} />
            </button>
          </div>
          <div className="inline-flex h-11 items-center gap-2 px-2">
            <button
              type="button"
              className="grid size-10 place-items-center text-[#5C5F6A]"
              aria-label="Previous page"
              onClick={() => setPage((p) => Math.max(1, p - 1))}
            >
              <IconChevronLeft size={12} />
            </button>
            {[1, 2].map((n) => (
              <button
                key={n}
                type="button"
                onClick={() => setPage(n)}
                className={cn(
                  "grid size-10 place-items-center rounded-full text-xs font-medium capitalize leading-6",
                  page === n ? "bg-icr-navy text-white" : "text-[#474B57]",
                )}
              >
                {n}
              </button>
            ))}
            <span className="grid size-10 place-items-center text-sm font-medium text-[#474B57]">
              …
            </span>
            {[23, 24].map((n) => (
              <button
                key={n}
                type="button"
                onClick={() => setPage(n)}
                className={cn(
                  "grid size-10 place-items-center rounded-full text-xs font-medium capitalize leading-6",
                  page === n ? "bg-icr-navy text-white" : "text-[#474B57]",
                )}
              >
                {n}
              </button>
            ))}
            <button
              type="button"
              className="grid size-10 place-items-center text-[#0E1422]"
              aria-label="Next page"
              onClick={() => setPage((p) => Math.min(24, p + 1))}
            >
              <IconChevronRight size={12} />
            </button>
          </div>
        </div>
      </section>

      <LeadDetailDrawer
        lead={selected}
        open={drawerOpen}
        onClose={closeDrawer}
      />
    </>
  );
}
