function SnapshotTooltip({ item }: { item: BarItem }) {
  return (
    <div
      className="relative w-[220px] rounded-2xl bg-white px-5 py-4 text-left shadow-[0_8px_28px_rgba(16,24,40,0.18)]"
      role="tooltip"
    >
      <div className="text-sm font-bold leading-5 text-icr-navy">{item.label}</div>
      <div className="mt-2 text-[13px] leading-5 text-icr-navy">
        <span className="font-bold">{item.current}</span> Total Leads this month
      </div>
      <div className="mt-0.5 text-[13px] leading-5 text-icr-navy">
        <span className="font-bold">{item.completedLastMonth}</span> Completed
        Last month.
      </div>
      <div className="my-3 h-px bg-icr-border" />
      <div className="text-[13px] leading-5 text-icr-navy">
        Baseline Median <span className="font-bold">{item.baselineMedian}</span>
      </div>
      <span
        className="absolute top-full left-1/2 -mt-px -translate-x-1/2 border-x-[7px] border-t-[8px] border-x-transparent border-t-white"
        aria-hidden
      />
    </div>
  );
}

function ChartCard({
  title,
  items,
  max,
  onBarClick,
}: {
  title: string;
  items: BarItem[];
  max: number;
  onBarClick?: (label: string) => void;
}) {
  return (
    <div className="overflow-visible rounded-[10px] border border-icr-border bg-icr-surface p-4">
      <h3 className="mb-3.5 mt-0 text-sm font-semibold text-icr-navy">{title}</h3>
      {items.map((item) => (
        <button
          type="button"
          className={cn(
            "group relative mb-3 grid w-full grid-cols-[110px_1fr_28px] items-center gap-2 text-left",
            onBarClick && "cursor-pointer rounded-md hover:bg-[#F8F9FA]",
            !onBarClick && "cursor-default",
          )}
          key={item.label}
          onClick={() => onBarClick?.(item.label)}
        >
          <div className="pointer-events-none invisible absolute bottom-full left-1/2 z-30 mb-2.5 -translate-x-1/2 opacity-0 transition-opacity duration-150 group-hover:visible group-hover:opacity-100 group-focus-visible:visible group-focus-visible:opacity-100">
            <SnapshotTooltip item={item} />
          </div>
          <div className="text-xs leading-4 text-icr-navy">{item.label}</div>
          <div className="flex min-w-0 flex-col gap-1">
            <div className="relative h-2 overflow-hidden rounded-full">
              <span
                className="relative block h-full rounded-full bg-icr-bar"
                style={{ width: `${(item.current / max) * 100}%` }}
              />
            </div>
            <div className="relative h-2 overflow-hidden rounded-full">
              <span
                className="relative block h-full rounded-full bg-icr-bar-prev"
                style={{ width: `${(item.previous / max) * 100}%` }}
              />
            </div>
          </div>
          <div className="text-right text-xs font-semibold text-icr-navy">
            {item.current}
          </div>
        </button>
      ))}
      <div className="mt-1 ml-[110px] flex justify-between pr-7 text-[11px] text-icr-muted">
        <span>0</span>
        <span>{Math.round(max * 0.25)}</span>
        <span>{Math.round(max * 0.5)}</span>
        <span>{Math.round(max * 0.75)}</span>
        <span>{max}</span>
      </div>
      <div className="mt-3 flex justify-center gap-4 text-xs text-icr-muted">
        <span className="inline-flex items-center gap-1.5">
          <i className="inline-block h-2 w-2 rounded-full bg-icr-bar" /> Current
          month
        </span>
        <span className="inline-flex items-center gap-1.5">
          <i className="inline-block h-2 w-2 rounded-full bg-[#d1d5db]" /> Previous
          month
        </span>
      </div>
    </div>
  );
}

export function PortfolioOverview() {
  const {
    region,
    product,
    regionActive,
    productActive,
    setRegion,
    setProduct,
  } = useDashboardFilters();

  const regions = useMemo(
    () =>
      regionActive
        ? regionItems.filter((item) => item.label === region)
        : regionItems,
    [region, regionActive],
  );

  const products = useMemo(
    () =>
      productActive
        ? productItems.filter((item) => item.label === product)
        : productItems,
    [product, productActive],
  );

  return (
    <section className="overflow-visible rounded-xl border border-icr-border bg-icr-surface p-5 shadow-[0_1px_2px_rgba(16,24,40,0.04)]">
      <div className="mb-4 flex items-start justify-between gap-3">
        <div>
          <div className="flex flex-wrap items-center gap-2">
            <h2 className="m-0 text-lg font-bold text-icr-navy">
              Portfolio overview
            </h2>
            <FilterScopeBadge />
          </div>
          <p className="mt-0.5 mb-0 text-[13px] text-icr-muted">
            Current vs previous month workload
          </p>
        </div>
        <div className="inline-flex items-center gap-1.5 text-xs text-icr-muted">
          <IconInfo />
          Click bar to filter leads in the register below.
        </div>
      </div>
      <div className="grid grid-cols-3 gap-4 overflow-visible max-[1280px]:grid-cols-1">
        <ChartCard
          title="Region Snapshot"
          max={100}
          items={regions}
          onBarClick={(label) => {
            if (
              label === "North America" ||
              label === "EMEA" ||
              label === "APAC"
            ) {
              setRegion(label);
            }
          }}
        />
        <ChartCard title="Top Customer" max={20} items={customerItems} />
        <ChartCard
          title="Product Snapshot"
          max={100}
          items={products}
          onBarClick={(label) => {
            if (label === "Quickflange" || label === "Techwrap") {
              setProduct(label);
            }
          }}
        />
      </div>
    </section>
  );
}
