"use client";

import { useEffect, useRef, useState } from "react";
import { useMobileNav } from "@/components/dashboard/MobileNav";
import {
  IconChevronDown,
  IconGlobe,
  IconHelp,
  IconSearch,
} from "@/components/icons";
import { cn } from "@/lib/utils";

const regions = ["Global", "North America", "EMEA", "APAC"] as const;

export function TopBar() {
  const { toggleSidebar } = useMobileNav();
  const [open, setOpen] = useState(false);
  const [region, setRegion] = useState<(typeof regions)[number]>("Global");
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDoc(e: MouseEvent) {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  return (
    <header className="sticky top-0 z-30 flex h-[61px] items-center justify-between gap-3 border-b border-icr-border bg-white px-4 lg:gap-4 lg:px-6">
      <div className="flex items-center gap-1 lg:hidden">
        <button
          type="button"
          aria-label="Open menu"
          onClick={toggleSidebar}
          className="inline-flex rounded-md bg-white p-2.5"
        >
          <img
            src="/assets/icons/sidebarHumberger.svg"
            alt=""
            width={20}
            height={20}
            className="size-5"
          />
        </button>
        <img
          src="/assets/images/logo.svg"
          alt="ICR"
          className="h-[18px] w-auto"
        />
        <button
          type="button"
          aria-label="Search"
          className="inline-flex rounded-md bg-white p-2.5"
        >
          <IconSearch size={20} className="text-[rgba(29,54,80,0.8)]" />
        </button>
      </div>

      <div ref={ref} className="relative hidden lg:block">
        <button
          type="button"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
          className="flex h-9 items-center gap-2 rounded-lg border border-icr-border-soft bg-icr-surface px-3 text-icr-navy"
        >
          <IconGlobe />
          <span className="text-[11px] font-semibold tracking-wide text-icr-muted">
            REGION
          </span>
          <span className="text-sm font-medium text-icr-navy">{region}</span>
          <span
            className={cn(
              "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
              open && "rotate-180",
            )}
          >
            <IconChevronDown />
          </span>
        </button>
        <div
          className={cn(
            "absolute top-[calc(100%+8px)] left-0 z-30 min-w-full origin-top transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
            open
              ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
              : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
          )}
        >
          <div className="overflow-hidden rounded-lg border border-icr-border bg-white py-1 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
            {regions.map((item) => (
              <button
                key={item}
                type="button"
                className={cn(
                  "flex w-full px-3 py-2 text-left text-sm hover:bg-[#F8F9FA]",
                  item === region
                    ? "font-medium text-icr-orange"
                    : "text-icr-navy",
                )}
                onClick={() => {
                  setRegion(item);
                  setOpen(false);
                }}
              >
                {item}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="flex items-center gap-1 lg:gap-3">
        <label className="hidden h-9 w-[280px] items-center gap-2 rounded-lg border border-icr-border bg-icr-surface px-3 font-[family-name:var(--font-geist)] text-icr-muted lg:flex">
          <IconSearch />
          <input
            type="search"
            placeholder="Search leads or customers…"
            className="w-full border-none bg-transparent text-icr-navy outline-none placeholder:text-icr-muted"
          />
        </label>
        <button
          type="button"
          className="hidden h-8 w-8 place-items-center rounded-lg text-icr-muted lg:grid"
          aria-label="Help"
        >
          <IconHelp />
        </button>
        <div className="flex items-center gap-1 lg:hidden">
          <button
            type="button"
            aria-label="Settings"
            className="inline-flex rounded-md bg-white p-2.5"
          >
            <img
              src="/assets/icons/settings.svg"
              alt=""
              width={20}
              height={20}
              className="size-5 opacity-65"
            />
          </button>
          <button
            type="button"
            aria-label="Notifications"
            className="inline-flex rounded-md bg-white p-2.5"
          >
            <img
              src="/assets/icons/Notification.svg"
              alt=""
              width={20}
              height={20}
              className="size-5 opacity-65"
            />
          </button>
        </div>
        <div
          className="grid h-10 w-10 place-items-center rounded-full bg-icr-orange text-xs font-semibold text-white outline outline-1 outline-[rgba(29,54,80,0.10)] lg:h-8 lg:w-8"
          aria-label="User SJ"
        >
          SJ
        </div>
      </div>
    </header>
  );
}
